{
  "name": "SalesReport",
  "formats": ["csv"],
  "description": "Books sold between two days (UTC, inclusive), as CSV",
  "operations": [
    {"method": "GET", "path": "/reports/sales", "format": "csv", "query": "sales.query.ts"}
  ],
  "parameters": {
    "from": {"in": "query", "type": "date", "required": true},
    "to": {"in": "query", "type": "date", "required": true, "handler": "sales_period.handler.ts"}
  },
  "properties": {
    "title": {"type": "string"},
    "quantity": {"type": "integer"},
    "revenueCents": {"type": "integer"}
  }
}
EOF
cat > resources/sales.query.ts <<'EOF'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`SELECT b.title AS title, sum(l.quantity)::int AS quantity,
    sum(l.quantity * l.unit_price_cents)::bigint AS "revenueCents"
    FROM purchase_line l
    JOIN purchase p ON p.id = l.purchase_id
    JOIN book b ON b.id = l.book_id
    WHERE (p.created_at AT TIME ZONE 'UTC') >= ${ctx.get("from")}::date
      AND (p.created_at AT TIME ZONE 'UTC') < (${ctx.get("to")}::date + 1)
    GROUP BY b.id, b.title
    ORDER BY "revenueCents" DESC, b.title ASC, b.id ASC`;
}
EOF
cat > resources/sales_period.handler.ts <<'EOF'
export default function salesPeriod(value: string, ctx) {
  if (ctx.get("from") > value) {
    ctx.reject({ message: "from must not be after to", pointer: "/to", hint: "Use from <= to, both YYYY-MM-DD." });
  }
  return null;
}
EOF
